(function ($) {
  $(document).ready(function () {
    $(window).resize(function () {
      $('.rdc-res').each(function () {
        equalise_articles($(this));
      });
    });

    $('.rdc-res').each(function () {
      var blog = $(this);
      equalise_articles($(this));

      var observer = new MutationObserver(function (mutations) {
        equalise_articles(blog);
      });

      var config = {
        subtree: true,
        childList: true
      };

      observer.observe(blog[0], config);
    });

    function equalise_articles(blog) {
      var articles = blog.find('article');
      var heights = [];

      // Reset heights first to get natural height
      articles.css('height', 'auto');

      articles.each(function () {
        var $article = $(this);
        var height = 0;

        // Add the pseudo-element height (50px) plus its margin (29px bottom)
        height += 79; // 50px height + 29px bottom margin

        var $title = $article.find('.entry-title');
        if ($title.length && $title.is(':visible')) {
          height += $title.outerHeight(true);
        }

        var $meta = $article.find('.post-meta');
        if ($meta.length && $meta.is(':visible')) {
          height += $meta.outerHeight(true);
        }

        var $content = $article.find('.post-content');
        if ($content.length && $content.is(':visible')) {
          height += $content.outerHeight(true);
        }

        heights.push(height);
      });

      var max_height = Math.max.apply(Math, heights);

      articles.each(function () {
        $(this).height(max_height);
      });
    }

    $(document).ajaxComplete(function () {
      $('.rdc-res').imagesLoaded().then(function () {
        $('.rdc-res').each(function () {
          equalise_articles($(this));
        });
      });
    });

    $.fn.imagesLoaded = function () {
      var $imgs = this.find('img[src!=""]');
      var dfds = [];

      if (!$imgs.length) {
        return $.Deferred().resolve().promise();
      }

      $imgs.each(function () {
        var dfd = $.Deferred();
        dfds.push(dfd);
        var img = new Image();

        img.onload = function () {
          dfd.resolve();
        };

        img.onerror = function () {
          dfd.resolve();
        };

        img.src = this.src;
      });

      return $.when.apply($, dfds);
    }
  });
})(jQuery);

(function ($) {
    $(document).ready(function () {
        function truncateExcerpts() {
            $('.rdc-res .et_pb_post .post-content p').each(function() {
                var $this = $(this);
                var text = $this.text();
                var wordLimit = 23; // Set your desired word count here

                if (text.split(' ').length > wordLimit) {
                    var truncated = text.split(' ').slice(0, wordLimit).join(' ') + '...';
                    $this.text(truncated);
                }
            });
        }

        // Run on page load
        truncateExcerpts();

        // Run after AJAX loads (for pagination, etc.)
        $(document).ajaxComplete(function() {
            setTimeout(function() {
                truncateExcerpts();
            }, 100);
        });

        // Run after images load
        $('.rdc-res').imagesLoaded().then(function() {
            truncateExcerpts();
        });

        // MutationObserver to watch for content changes
        $('.rdc-res').each(function() {
            var observer = new MutationObserver(function(mutations) {
                truncateExcerpts();
            });

            var config = {
                subtree: true,
                childList: true
            };

            if (this) {
                observer.observe(this, config);
            }
        });
    });
})(jQuery);

