div.script:
(function () {
  if (!window.rdcMarkFlipCardsRow) {
    window.rdcMarkFlipCardsRow = function (cardEl) {
      if (!cardEl || !cardEl.closest) return;
      var row = cardEl.closest('.et_pb_row');
      if (row) row.classList.add('rdc-flip-cards-row');
    };
  }

  var cardRoot = document.getElementById('rdc-single-pi-early-warnings');
  if (cardRoot) {
    window.rdcMarkFlipCardsRow(cardRoot);

    var front = cardRoot.querySelector('.rdc-fc-pi-early-warnings__front');
    var back  = cardRoot.querySelector('.rdc-fc-pi-early-warnings__back');

    if (front && back) {
      /* iOS fix: backface-visibility is unreliable on WebKit — explicitly
         hide the rotating-away face at the halfway point of each transition
         (when the card is edge-on and neither face is visible). */
      back.style.visibility = 'hidden';

      var flipTimer;
      cardRoot.addEventListener('click', function (e) {
        if (e.target.closest('a')) return;
        clearTimeout(flipTimer);
        var willBeFlipped = !cardRoot.classList.contains('is-flipped');
        flipTimer = setTimeout(function () {
          front.style.visibility = willBeFlipped ? 'hidden' : '';
          back.style.visibility  = willBeFlipped ? ''       : 'hidden';
        }, 200);
      });
    }
  }

  if (!window.rdcFlipSingle) {
    window.rdcFlipSingle = function (cardId) {
      var card = document.getElementById(cardId);
      if (card) card.classList.toggle('is-flipped');
    };
    document.addEventListener('click', function (e) {
      if (e.target.closest('a')) return;
      var card = e.target.closest('.rdc-fc-single');
      if (!card) return;
      rdcFlipSingle(card.id);
    });
  }
})();

