(function () {
  if (!window.rdcMarkFlipCardsRow) {
    window.rdcMarkFlipCardsRow = function (cardEl) {
      if (!cardEl || !cardEl.closest) return;
      var row = cardEl.closest('.et_pb_row');
      if (row) row.classList.add('rdc-flip-cards-row');
    };
  }

  var cardRoot = document.getElementById('rdc-single-1');
  if (cardRoot) {
    window.rdcMarkFlipCardsRow(cardRoot);

    var front = cardRoot.querySelector('.rdc-fc-cashflow__front');
    var back  = cardRoot.querySelector('.rdc-fc-cashflow__back');

    if (front && back) {
      back.style.visibility = 'hidden';
      var flipTimer;
      cardRoot.addEventListener('click', function (e) {
