      var card = e.target.closest('.rdc-fc-cashflow');
      if (!card) return;
      rdcFlipCashflow(card.id);
    });
  }
})();

(function () {
  var card = document.getElementById('rdc-wide-2');
  if (!card) return;

  if (!window.rdcMarkFlipCardsRow) {
    window.rdcMarkFlipCardsRow = function (cardEl) {
      if (!cardEl || !cardEl.closest) return;
      var row = cardEl.closest('.et_pb_row');
      if (row) row.classList.add('rdc-flip-cards-row');
    };
  }

  window.rdcMarkFlipCardsRow(card);

  var wFront = card.querySelector('.rdc-fc-wide__front');
  var wBack  = card.querySelector('.rdc-fc-wide__back');
  if (wFront && wBack) wBack.style.visibility = 'hidden';
  var wFlipTimer;

  card.addEventListener('click', function (e) {
    e.stopPropagation();
    if (e.target.closest('a')) return;
    if (e.target.closest('.rdc-fc-carousel-dot') || e.target.closest('.rdc-fc-back-carousel-dot')) return;

    clearTimeout(wFlipTimer);
    var willBeFlipped = !card.classList.contains('is-flipped');
    card.classList.toggle('is-flipped');
    wFlipTimer = setTimeout(function () {
      wFront.style.visibility = willBeFlipped ? 'hidden' : '';
      wBack.style.visibility  = willBeFlipped ? ''       : 'hidden';
    }, 200);
  });

  /* ── Front-face carousel (≤980px) ─────────────────────── */
  if (!window.rdcCarouselInit) {
    window.rdcCarouselInit = true;
    function rdcInitFrontCarousel(card) {
      var panels = card.querySelector('.rdc-fc-panels');
      if (!panels || panels.dataset.carouselDone) return;
      panels.dataset.carouselDone = 'true';

      /* Wrap panels in a track div */
      var panelItems = Array.prototype.slice.call(panels.querySelectorAll(':scope > .rdc-fc-panel'));
      var track = document.createElement('div');
      track.className = 'rdc-fc-panels-track';
      panelItems.forEach(function(p) { track.appendChild(p); });
      panels.insertBefore(track, panels.firstChild);

      /* Build dot indicators */
      var dotsEl = document.createElement('div');
      dotsEl.className = 'rdc-fc-carousel-dots';
      panelItems.forEach(function(_, i) {
        var dot = document.createElement('button');
        dot.type = 'button';
        dot.className = 'rdc-fc-carousel-dot' + (i === 0 ? ' is-active' : '');
        dot.setAttribute('aria-label', 'Go to panel ' + (i + 1));
        dot.dataset.index = i;
        dotsEl.appendChild(dot);
      });

      var dotsWrap = document.createElement('div');
      dotsWrap.className = 'rdc-fc-carousel-dots-wrap';
      dotsWrap.appendChild(dotsEl);
      panels.parentNode.insertBefore(dotsWrap, panels.nextSibling);

      var current = 0;
      function goTo(idx) {
        current = Math.max(0, Math.min(idx, panelItems.length - 1));
        var shift = 'translateX(' + (-100 * current) + '%)';
        track.style.webkitTransform = shift;
        track.style.transform = shift;
        dotsEl.querySelectorAll('.rdc-fc-carousel-dot').forEach(function(d, i) {
          d.classList.toggle('is-active', i === current);
        });
      }

      /* Dot click — stop propagation to prevent card flip */
      dotsEl.addEventListener('click', function(e) {
        e.stopPropagation();
        var dot = e.target.closest('.rdc-fc-carousel-dot');
        if (!dot) return;
        goTo(parseInt(dot.dataset.index, 10));
      });

      /* Touch swipe */
      var touchStartX = 0;
      track.addEventListener('touchstart', function(e) {
        touchStartX = e.touches[0].clientX;
      }, { passive: true });
      track.addEventListener('touchend', function(e) {
        var dx = e.changedTouches[0].clientX - touchStartX;
        if (Math.abs(dx) > 40) {
          goTo(dx < 0 ? current + 1 : current - 1);
          e.stopPropagation();
        }
      }, { passive: true });
    }

    /* Init all wide cards on page */
    document.querySelectorAll('.rdc-fc-wide').forEach(rdcInitFrontCarousel);
  }

  /* ── Back-face tabs (desktop only) ─────────── */
  if (!window.rdcBackTabsInit) {
    window.rdcBackTabsInit = true;
    function rdcInitBackTabs(cardEl) {
      var tabButtons = cardEl.querySelectorAll('.rdc-fc-back-tab');
      if (!tabButtons.length) return;

      var tabPanels = cardEl.querySelectorAll('.rdc-fc-tab-panel');
      if (!tabPanels.length) return;

      tabButtons.forEach(function(button) {
        button.addEventListener('click', function(e) {
          e.stopPropagation();
          var tabId = button.dataset.tab;
          var targetPanel = cardEl.querySelector('#rdc-wide-2-' + tabId);
          if (!targetPanel) return;

          // Deactivate all tabs and panels
          tabButtons.forEach(function(btn) {
            btn.classList.remove('is-active');
          });
          tabPanels.forEach(function(panel) {
            panel.classList.remove('is-active');
          });

          // Activate selected tab and panel
          button.classList.add('is-active');
          targetPanel.classList.add('is-active');
        });
      });
    }

    /* Init back tabs for all wide cards */
    document.querySelectorAll('.rdc-fc-wide').forEach(rdcInitBackTabs);
  }

  /* ── Back-face carousel (swipe between panels) ─────────── */
  if (!window.rdcBackCarouselInit) {
    window.rdcBackCarouselInit = true;
    function rdcInitBackCarousel(cardEl) {
      var backPanels = cardEl.querySelector('.rdc-fc-back-panels');
      if (!backPanels || backPanels.dataset.backCarouselDone) return;
      backPanels.dataset.backCarouselDone = 'true';

      var backTrack = cardEl.querySelector('.rdc-fc-back-panels-track');
      if (!backTrack) return;

      /* Clone tab panels into carousel track for mobile mode.
         The originals are direct children of .rdc-fc-face-clip (not of
         .rdc-fc-wide__back), and the clones live deeper inside
         .rdc-fc-back-panels-track — so scope to .rdc-fc-face-clip's direct
         children to grab only the originals. */
      var originalPanels = Array.prototype.slice.call(cardEl.querySelectorAll('.rdc-fc-wide__back .rdc-fc-face-clip > .rdc-fc-tab-panel'));
      originalPanels.forEach(function(panel) {
        var clone = panel.cloneNode(true);
        clone.classList.remove('is-active');
        backTrack.appendChild(clone);
      });

      var panelItems = Array.prototype.slice.call(backTrack.querySelectorAll('.rdc-fc-tab-panel'));
      if (!panelItems.length) return;

      /* Build back dot indicators */
      var dotsWrap = cardEl.querySelector('.rdc-fc-back-carousel-dots-wrap');
      var dotsContainer = dotsWrap ? dotsWrap.querySelector('.rdc-fc-back-carousel-dots') : null;
      if (!dotsContainer) return;

      panelItems.forEach(function(_, i) {
        var dot = document.createElement('button');
        dot.type = 'button';
        dot.className = 'rdc-fc-back-carousel-dot' + (i === 0 ? ' is-active' : '');
        dot.setAttribute('aria-label', 'Go to panel ' + (i + 1));
        dot.dataset.index = i;
        dotsContainer.appendChild(dot);
      });

      var titleOverlay = cardEl.querySelector('.rdc-fc-back-title-overlay');

      var current = 0;
      function goToBack(idx) {
        current = Math.max(0, Math.min(idx, panelItems.length - 1));
        var shift = 'translateX(' + (-100 * current) + '%)';
        backTrack.style.webkitTransform = shift;
        backTrack.style.transform = shift;
        dotsContainer.querySelectorAll('.rdc-fc-back-carousel-dot').forEach(function(d, i) {
          d.classList.toggle('is-active', i === current);
        });
        var activePanel = panelItems[current];
        if (titleOverlay && activePanel) {
          titleOverlay.textContent = activePanel.getAttribute('data-title') || '';
        }
      }

      /* Dot click — stop propagation to prevent card flip */
      dotsContainer.addEventListener('click', function(e) {
        e.stopPropagation();
        var dot = e.target.closest('.rdc-fc-back-carousel-dot');
        if (!dot) return;
        goToBack(parseInt(dot.dataset.index, 10));
      });

      /* Touch swipe */
      var touchStartX = 0;
      backTrack.addEventListener('touchstart', function(e) {
        touchStartX = e.touches[0].clientX;
      }, { passive: true });
      backTrack.addEventListener('touchend', function(e) {
        var dx = e.changedTouches[0].clientX - touchStartX;
        if (Math.abs(dx) > 40) {
          goToBack(dx < 0 ? current + 1 : current - 1);
          e.stopPropagation();
        }
      }, { passive: true });
    }

    /* Init back carousels for all wide cards */
    document.querySelectorAll('.rdc-fc-wide').forEach(rdcInitBackCarousel);
  }
})();

(function () {
  if (!window.rdcMarkFlipCardsRow) {
    window.rdcMarkFlipCardsRow = function (cardEl) {
      if (!cardEl || !cardEl.closest) return;
      var row = cardEl.closest('.et_pb_row');
      if (row) row.classList.add('rdc-flip-cards-row');
    };
  }

  var cardRoot = document.getElementById('rdc-single-maturing-facilities');
  if (cardRoot) {
    window.rdcMarkFlipCardsRow(cardRoot);

    var front = cardRoot.querySelector('.rdc-fc-maturing__front');
    var back  = cardRoot.querySelector('.rdc-fc-maturing__back');

    if (front && back) {
      back.style.visibility = 'hidden';
      var flipTimer;
      cardRoot.addEventListener('click', function (e) {
        if (e.target.closest('a')) return;
        clearTimeout(flipTimer);
        var willBeFlipped = !cardRoot.classList.contains('is-flipped');
        flipTimer = setTimeout(function () {
          front.style.visibility = willBeFlipped ? 'hidden' : '';
          back.style.visibility  = willBeFlipped ? ''       : 'hidden';
        }, 200);
      });
    }
  }

  /* ── Single card flip toggle ──────────────────────────────── */
  if (!window.rdcFlipMaturing) {
    window.rdcFlipMaturing = function (cardId) {
      var card = document.getElementById(cardId);
      if (card) card.classList.toggle('is-flipped');
    };
    document.addEventListener('click', function (e) {
      if (e.target.closest('a')) return;
      var card = e.target.closest('.rdc-fc-maturing');
      if (!card) return;
      rdcFlipMaturing(card.id);
    });
  }
})();

