/*
  RDC - Divi reliable wave background animation (JS-driven)
  Targets sections with class: rdc-wave-bg-animated
*/
(function () {
  function initRdcWaveBackgroundAnimation() {
    var prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (prefersReducedMotion) return;

    var sections = document.querySelectorAll('.rdc-wave-bg-animated');
    if (!sections.length) return;

    var speedPxPerSecond = 24;
    var bobAmplitude = 4;
    var bobPeriodMs = 8000;
    var state = [];

    sections.forEach(function (section) {
      if (section.dataset.rdcWaveInitialized === 'true') return;

      var computed = window.getComputedStyle(section);
      var bgImage = computed.backgroundImage;
      if (!bgImage || bgImage === 'none') return;

      var layer = document.createElement('div');
      layer.className = 'rdc-wave-bg-layer';
      layer.style.setProperty('background-image', bgImage, 'important');
      layer.style.setProperty('background-position', '0 100%', 'important');
      layer.style.setProperty('background-size', 'auto 100%', 'important');

      section.insertBefore(layer, section.firstChild);
      section.style.setProperty('background-image', 'none', 'important');
      section.style.setProperty('background-color', computed.backgroundColor);
      section.dataset.rdcWaveInitialized = 'true';

      state.push({
        layer: layer,
        offset: 0,
        loopWidth: 1702
      });
    });

    if (!state.length) return;

    var lastTime = performance.now();

    function tick(now) {
      var deltaMs = now - lastTime;
      lastTime = now;

      var baseScale = window.innerWidth <= 767 ? 130 : (window.innerWidth <= 980 ? 115 : 100);
      var bobScale = 100 + Math.sin((now / bobPeriodMs) * Math.PI * 2) * bobAmplitude;

      state.forEach(function (item) {
        item.offset = (item.offset + (speedPxPerSecond * deltaMs) / 1000) % item.loopWidth;
        item.layer.style.setProperty('background-position', item.offset.toFixed(2) + 'px 100%', 'important');
        item.layer.style.setProperty('background-size', 'auto ' + (baseScale + (bobScale - 100)).toFixed(2) + '%', 'important');
      });

      requestAnimationFrame(tick);
    }

    requestAnimationFrame(tick);
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', initRdcWaveBackgroundAnimation);
  } else {
    initRdcWaveBackgroundAnimation();
  }

  window.addEventListener('load', initRdcWaveBackgroundAnimation);
})();

